/* Account-separated HTML filter workflow. Synthetic records only; no native evaluator or writes. */
(function(){
'use strict';
const stores=new Map(),copy=value=>JSON.parse(JSON.stringify(value));
const fields=[['SUBREDDIT','Subreddit'],['USER','User'],['FLAIR','Flair'],['DOMAIN','Domain'],['TITLE_KEYWORD','Title keyword'],['TITLE_REGEX','Title regex']];
const usageTypes=[[0,'All feeds'],[1,'Home'],[2,'Subreddit'],[3,'User'],[4,'Multireddit'],[5,'Search'],[6,'History'],[7,'Upvoted'],[8,'Downvoted'],[9,'Hidden'],[10,'Saved']];
const wildcardTarget='ContinuumAll'; // Existing scope identity, not app branding. Its listing fetches r/all.
let session=null,context=null,serial=0;
function el(tag,cls,text){const node=document.createElement(tag);if(cls)node.className=cls;if(text!==undefined)node.textContent=text;return node}
function blank(kind){return {id:'fixture-'+(++serial),name:'',rules:[],usages:[],types:{Text:true,Link:true,Image:true,GIF:true,Video:true,Gallery:true},onlyNSFW:false,onlySpoiler:false,votes:'',comments:'',excludeStrings:'',excludeUsers:'',displayMode:'0',minVote:'',maxVote:''}}
function store(account,kind){const key=account+'|'+kind;if(!stores.has(key)){const sample=blank(kind);sample.name=kind==='post'?'Travel topics':'Comment reading';sample.rules=[{field:'TITLE_KEYWORD',exclude:true,value:'giveaway'},{field:'DOMAIN',exclude:true,value:'example.org'}];sample.usages=kind==='post'?[{type:1,name:'--'},{type:2,name:'hiking'}]:[{type:1,name:'hiking'}];const scenario=new URLSearchParams(location.search).get('filter-rules');if(kind==='post'&&['wildcard','mixed'].includes(scenario)){sample.rules=scenario==='mixed'?[...sample.rules,{field:'SUBREDDIT',exclude:true,value:'*trail*'}]:[{field:'SUBREDDIT',exclude:true,value:'*trail*'}];sample.usages=[{type:2,name:wildcardTarget}]}sample.excludeStrings='giveaway, referral';sample.excludeUsers='sampleuser';stores.set(key,{items:new URLSearchParams(location.search).get('filters')==='empty'?[]:[sample],selected:sample.id,failUsed:false})}return stores.get(key)}
function currentItem(){return context.data.items.find(item=>item.id===context.data.selected)}
function begin(item){session={account:context.account,kind:context.kind,draft:copy(item||blank(context.kind)),original:item?.id||null,baseline:JSON.stringify(item||null)};if(!item)session.baseline=JSON.stringify(session.draft)}
function dirty(){return !!session&&JSON.stringify(session.draft)!==session.baseline}
function wildcard(rule){return rule.field==='SUBREDDIT'&&(rule.value.startsWith('*')||rule.value.endsWith('*'))}
function pinned(item){return item.rules.some(wildcard)}
function accepts(rules,candidate,original){if(original&&wildcard(original)===wildcard(candidate))return true;return rules.filter(rule=>rule!==original).every(rule=>wildcard(rule)===wildcard(candidate))}
function sameRule(a,b){return a.field===b.field&&a.exclude===b.exclude&&a.value.toLowerCase()===b.value.toLowerCase()}
function int(text){if(!/^[+-]?\d+$/.test(text.trim()))return null;const value=Number(text);return Number.isInteger(value)&&value>=-2147483648&&value<=2147483647?value:null}
function range(text){const value=text.trim();if(!value||value.startsWith('-'))return [-1,-1];const at=value.indexOf('-'),parts=at<0?[value,'']:[value.slice(0,at),value.slice(at+1)];return parts.map(part=>{const value=int(part);return value>0?value:-1})}
function section(root,title){const node=el('section','settings-group filter-section');node.append(el('h3',null,title));const body=el('div','settings-rows filter-panel');node.append(body);root.append(node);return body}
function button(root,text,action,id){const node=el('button',null,text);node.type='button';if(id){node.id=id;node.dataset.category=id}node.addEventListener('click',action);root.append(node);return node}
function note(root,text){root.append(el('p','field-help',text))}
function announce(text){const status=context.root.querySelector('#filter-feedback');if(status)status.textContent=text;else context.announce(text)}
function input(root,title,value,changed,options={}){const wrap=el('div','filter-field'),label=el('label',null,title),control=el(options.multiline?'textarea':options.options?'select':'input');control.id='filter-'+(options.id||title.toLowerCase().replace(/[^a-z0-9]+/g,'-'));label.htmlFor=control.id;if(control.tagName==='INPUT'||!options.options&&!options.multiline)control.type='text';
 if(options.options)for(const [value,text]of options.options){const option=el('option',null,text);option.value=String(value);control.append(option)}
 control.value=value;if(options.numeric)control.inputMode='text';control.addEventListener(options.options?'change':'input',()=>changed(control.value));wrap.append(label,control);if(options.help){const help=el('small',null,options.help);help.id=control.id+'-help';control.setAttribute('aria-describedby',help.id);wrap.append(help)}root.append(wrap);return control}
function toggle(root,title,value,changed){const row=el('div','video-setting'),label=el('span',null,title),control=el('button','video-toggle');control.type='button';label.id='filter-label-'+title.replaceAll(' ','-');control.setAttribute('role','switch');control.setAttribute('aria-labelledby',label.id);control.setAttribute('aria-checked',String(value));control.addEventListener('click',()=>{value=!value;control.setAttribute('aria-checked',String(value));changed(value)});row.append(label,control);root.append(row)}
function routeRow(root,title,summary,action,id){const row=el('div','filter-item'),copy=el('div');copy.append(el('strong',null,title));if(summary)copy.append(el('small',null,summary));row.append(copy);button(row,'Options',action,id);root.append(row)}
function modal(title,build){const origin=document.activeElement,dialog=el('dialog','filter-modal');dialog.id='filter-modal';const heading=el('h3',null,title);heading.id='filter-modal-title';dialog.setAttribute('aria-labelledby',heading.id);const body=el('div','filter-modal-body'),feedback=el('p','field-help'),actions=el('div','dialog-actions');feedback.setAttribute('role','status');dialog.append(heading,body,feedback,actions);context.root.append(dialog);
 dialog.addEventListener('close',()=>dialog.remove(),{once:true});const close=()=>{dialog.close();if(origin?.isConnected)origin.focus({preventScroll:true})};const cancel=button(actions,'Cancel',close);cancel.autofocus=true;dialog.addEventListener('cancel',event=>{event.preventDefault();close()});dialog.addEventListener('keydown',event=>{if(event.key==='Escape')event.stopPropagation()});build({dialog,body,actions,feedback,close});dialog.showModal();return dialog}
function confirm(title,message,label,action,cancelLabel){modal(title,({body,actions,close})=>{if(cancelLabel)actions.children[0].textContent=cancelLabel;note(body,message);button(actions,label,()=>{close();action()})})}
function refresh(focusId){const root=context.root,scroll=document.getElementById('settings-scroll'),offset=scroll?.scrollTop;root.replaceChildren();draw();if(scroll)scroll.scrollTop=offset;root.querySelector('#'+focusId)?.focus({preventScroll:true})}
function usageLabel(usage,kind){if(kind==='comment')return 'r/'+usage.name;if(usage.name===wildcardTarget)return 'All · wildcard filtering';const type=usageTypes.find(pair=>pair[0]===usage.type)?.[1]||'Feed';return usage.name==='--'?(usage.type>=2&&usage.type<=4?'All '+type.toLowerCase()+'s':type):type+' · '+usage.name}
function commitRule(candidate,index){const item=session.draft,old=item.rules[index];if(old)item.rules.splice(index,1);if(!item.rules.some(rule=>sameRule(rule,candidate)))item.rules.push(candidate);if(pinned(item))item.usages=[{type:2,name:wildcardTarget}];refresh('filter-add-rule');announce('Rule updated'+(pinned(item)?'. This filter is pinned to All · wildcard filtering.':'.'))}
function ruleSheet(index){const old=session.draft.rules[index],item=session.draft,form=copy(old||{field:'SUBREDDIT',exclude:true,value:''});let mode=old&&wildcard(old)?(old.value.startsWith('*')?(old.value.endsWith('*')?'contains':'suffix'):'prefix'):'exact';if(form.field==='SUBREDDIT')form.value=form.value.replace(/^\*|\*$/g,'');
 modal(old?'Edit rule':'Add rule',({body,actions,feedback,close})=>{
  input(body,'Field',form.field,value=>{form.field=value;if(value!=='SUBREDDIT'){mode='exact';match.value='exact'}sync()}, {id:'rule-field',options:fields});input(body,'Match',String(form.exclude),value=>{form.exclude=value==='true';sync()}, {id:'rule-polarity',options:[['true','Exclude matches'],['false','Only include matches']]});
  const match=input(body,'Subreddit name match',mode,value=>{mode=value;sync()}, {id:'rule-mode',options:[['exact','Exact name'],['prefix','Starts with'],['suffix','Ends with'],['contains','Contains']]});
  const value=input(body,'Value',form.value,value=>{form.value=value;sync()}, {id:'rule-value',help:'One term per rule. Title regex uses Java regular-expression syntax.'});
  const picker=button(body,'Choose from a list',()=>{feedback.textContent='Existing '+(form.field==='USER'?'user':'subreddit')+' picker route. This study loads no live Reddit lists.'});
  const save=button(actions,old?'Update rule':'Add rule',()=>{const candidate=make();const displaced=item.rules.findIndex((rule,i)=>i!==index&&candidate.field==='TITLE_REGEX'&&rule.field===candidate.field&&rule.exclude===candidate.exclude);close();if(displaced>=0)confirm('Replace title regex?','This filter already has a title regex for this include/exclude choice. Replace it?','Replace',()=>{const currentOld=item.rules[index];item.rules.splice(displaced,1);commitRule(candidate,currentOld?item.rules.indexOf(currentOld):-1)});else commitRule(candidate,index)});
  function make(){const value=form.value.trim(),stored=form.field!=='SUBREDDIT'||mode==='exact'?value:mode==='prefix'?value+'*':mode==='suffix'?'*'+value:'*'+value+'*';return {field:form.field,exclude:form.exclude,value:stored}}
  function sync(){match.parentElement.hidden=form.field!=='SUBREDDIT';picker.hidden=!['SUBREDDIT','USER'].includes(form.field);const candidate=make(),raw=form.value.trim();let error='';if(raw){if(form.field!=='TITLE_REGEX'&&raw.includes(','))error='Enter one term without commas.';else if(form.field==='SUBREDDIT'&&raw.includes('*'))error='Use the name-match selector instead of typing *.';else if(wildcard(candidate)&&raw.length<3)error='Use at least 3 characters for this match.';else if(!accepts(item.rules,candidate,old))error='Keep wildcard subreddit rules separate from other rules.';else if(item.rules.some((rule,i)=>i!==index&&sameRule(rule,candidate)))error='This rule is already present.';else if(form.field==='TITLE_REGEX'&&new URLSearchParams(location.search).get('filter-regex')==='invalid')error='Invalid regular expression.'}save.disabled=!raw||!!error;value.setAttribute('aria-invalid',String(!!error));feedback.textContent=error||(wildcard(candidate)?'This match pins the filter to All · wildcard filtering. Other feed assignments are removed.':'');}
  sync();
 });
}
function usageSheet(index){const comment=context.kind==='comment',item=comment?currentItem():session.draft,old=item.usages[index];if(!comment&&pinned(item)){announce('Remove wildcard subreddit rules before changing feed assignments.');return}
 modal(old?'Edit assignment':'Add assignment',({body,actions,feedback,close})=>{let type=old?.type||(comment?1:1),name=old&&old.name!=='--'?old.name:'';
  if(comment&&old)note(body,'Changing the name adds a new assignment. Remove the previous assignment separately.');
  if(!comment)input(body,'Feed type',String(type),value=>{type=+value;sync()}, {id:'usage-type',options:usageTypes});
  const text=input(body,comment?'Subreddit':'Name or path',name,value=>{name=value;sync()}, {id:'usage-name',help:comment?'Enter a subreddit name.':'For subreddit, user and multireddit: blank means all within this type. Separate names with commas.'});
  const picker=button(body,'Choose from a list',()=>{feedback.textContent='Existing '+(type===3&&!comment?'user':'subreddit')+' picker route. This study loads no live Reddit lists.'});
  const apply=button(actions,comment?'Apply':'Add',()=>{if(old&&!comment)item.usages.splice(index,1);const entries=comment?[{type:1,name}]:type===0?[1,2,3,4].map(type=>({type,name:'--'})):[2,3,4].includes(type)?(name.split(',').map(n=>n.trim()).filter(Boolean).map(name=>({type,name}))):[{type,name:'--'}];if(!entries.length)entries.push({type,name:'--'});for(const entry of entries)if(!item.usages.some(u=>u.type===entry.type&&(comment?u.name===entry.name:u.name.toLowerCase()===entry.name.toLowerCase())))item.usages.push(entry);close();refresh('filter-add-usage');announce(comment?'Subreddit assignment applied to this fixture.':'Assignment added. Save the filter to keep these changes in this fixture.');});
  function sync(){text.parentElement.hidden=!comment&&![2,3,4].includes(type);picker.hidden=comment||![2,3].includes(type);apply.disabled=comment&&name==='';}sync();
 });
}
function removeRule(index){const rules=session.draft.rules,removed=rules[index],wasMixed=rules.some(wildcard)&&rules.some(rule=>!wildcard(rule));rules.splice(index,1);refresh('filter-add-rule');announce('Rule removed.');const status=context.root.querySelector('#filter-feedback');button(status,'Undo',()=>{if(!wasMixed&&!accepts(rules,removed)){announce('Undo is unavailable because this filter now holds another rule kind.');return}if(!rules.some(rule=>sameRule(rule,removed)))rules.splice(Math.min(index,rules.length),0,removed);refresh('filter-add-rule')})}
function usages(root,item){const panel=section(root,'Applies to');if(!item.usages.length)note(panel,'Not applied to any feed.');for(const [index,usage]of item.usages.entries()){const row=el('div','filter-item');row.append(el('strong',null,usageLabel(usage,context.kind)));const actions=el('div','filter-actions');const edit=button(actions,'Edit',()=>usageSheet(index)),remove=button(actions,'Remove',()=>{item.usages.splice(index,1);refresh('filter-add-usage');announce(context.kind==='comment'?'Assignment removed from this fixture.':'Assignment removed. Save to keep the change in this fixture.');if(context.kind==='post')button(context.root.querySelector('#filter-feedback'),'Undo',()=>{if(pinned(item)&&usage.name!==wildcardTarget){announce('Remove wildcard rules before restoring this assignment.');return}if(!item.usages.some(u=>u.type===usage.type&&u.name===usage.name))item.usages.splice(Math.min(index,item.usages.length),0,usage);refresh('filter-add-usage')})});edit.disabled=remove.disabled=context.kind==='post'&&pinned(item);row.append(actions);panel.append(row)}const add=button(panel,context.kind==='comment'?'Add subreddit':'Add feed',()=>usageSheet(-1),'filter-add-usage');add.disabled=context.kind==='post'&&pinned(item);if(add.disabled)note(panel,'Wildcard rules require All · wildcard filtering. Remove those rules to choose other feeds.');}
function save(){const item=session.draft,name=context.kind==='post'?item.name.trim():item.name;if(name===''){announce('Name this filter before saving.');context.root.querySelector('#filter-name').focus();return}if(context.kind==='comment'&&['minVote','maxVote'].some(key=>item[key]!==''&&int(item[key])===null)){announce('Enter whole-number vote bounds within the supported range, or leave them empty.');return}
 const duplicate=context.data.items.find(value=>value.id!==session.original&&value.name===name),perform=()=>{if(new URLSearchParams(location.search).get('filter-save')==='fail'&&!context.data.failUsed){context.data.failUsed=true;announce('Save did not complete. Your changes are kept. Try again.');return}const saved=copy(item);saved.name=name;if(context.kind==='comment'){saved.minVoteValue=item.minVote===''?-1:int(item.minVote);saved.maxVoteValue=item.maxVote===''?-1:int(item.maxVote)}if(context.kind==='post'){saved.voteBounds=range(saved.votes);saved.commentBounds=range(saved.comments)}if(duplicate)context.data.items=context.data.items.filter(value=>value.id!==duplicate.id);const at=context.data.items.findIndex(value=>value.id===session.original);if(at<0)context.data.items.push(saved);else context.data.items[at]=saved;context.data.selected=saved.id;session=null;context.goBack();context.announce('Filter saved in the page-memory fixture only. No native filter or feed changed.');};if(duplicate)confirm('Replace existing filter?','A filter named “'+name+'” already exists in this account.','Replace',perform);else perform();}
function draw(){const {root,kind,view,data,navigate}=context,post=kind==='post',title=post?'Post':'Comment';
 if(view.endsWith('-filters')){session=null;const panel=section(root,title+' filters');button(panel,'Create '+title.toLowerCase()+' filter',()=>{begin();navigate(kind+'-filter-editor','filter-create')},'filter-create');if(!data.items.length)note(panel,'No '+title.toLowerCase()+' filters for this account.');for(const item of data.items)routeRow(panel,item.name,item.usages.length+' assignment'+(item.usages.length===1?'':'s'),()=>{data.selected=item.id;navigate(kind+'-filter-options','filter-item-'+item.id)},'filter-item-'+item.id);}
 else if(view.endsWith('-options')){session=null;const item=currentItem();if(!item){note(root,'This filter is no longer available.');return}const panel=section(root,item.name);button(panel,'Edit',()=>{begin(item);navigate(kind+'-filter-editor','filter-edit')},'filter-edit');if(!post)button(panel,'Apply to',()=>navigate('comment-filter-targets','filter-apply'),'filter-apply');button(panel,'Delete',()=>{data.items=data.items.filter(value=>value.id!==item.id);context.goBack();context.announce('Filter and its assignments removed from the synthetic fixture only.');});}
 else if(view==='comment-filter-targets'){session=null;const item=currentItem();if(item)usages(root,item);else note(root,'Save a named comment filter before assigning subreddits.');}
 else{if(!session||session.account!==context.account||session.kind!==kind)begin(currentItem());const item=session.draft;input(section(root,'Name'),'Name',item.name,value=>item.name=value,{id:'name',help:'Required to save a named filter.'});
  if(post){const panel=section(root,'Rules');input(panel,'Find rules','',value=>{for(const row of panel.querySelectorAll('[data-rule-search]'))row.hidden=!row.dataset.ruleSearch.includes(value.toLowerCase())},{id:'find-rules',help:'Filters this list only; all rules are saved.'});if(!item.rules.length)note(panel,'No rules yet.');for(const {index,rule}of item.rules.map((rule,index)=>({rule,index})).sort((a,b)=>fields.findIndex(pair=>pair[0]===a.rule.field)-fields.findIndex(pair=>pair[0]===b.rule.field)||Number(b.rule.exclude)-Number(a.rule.exclude))){const row=el('div','filter-item');row.dataset.ruleSearch=(rule.field+' '+rule.value+' '+(rule.exclude?'exclude':'include')).toLowerCase();row.append(el('strong',null,(rule.exclude?'Exclude ':'Only include ')+(fields.find(pair=>pair[0]===rule.field)?.[1]||rule.field)+': '+rule.value));const actions=el('div','filter-actions');button(actions,'Edit',()=>ruleSheet(index));button(actions,'Remove',()=>removeRule(index));if(wildcard(rule))button(actions,'Blocked subreddits',()=>context.announce('Existing account/rule-scoped blocked-list and exception route. No live blocked records are loaded.'));row.append(actions);panel.append(row)}button(panel,'Add rule',()=>ruleSheet(-1),'filter-add-rule');usages(root,item);const types=section(root,'Post types');for(const [name,value]of Object.entries(item.types))toggle(types,name,value,value=>item.types[name]=value);const show=section(root,'Show only');toggle(show,'Only NSFW',item.onlyNSFW,value=>item.onlyNSFW=value);toggle(show,'Only spoilers',item.onlySpoiler,value=>item.onlySpoiler=value);const limits=section(root,'Limits');for(const [key,label]of [['votes','Votes'],['comments','Comment count']])input(limits,label,item[key],value=>{item[key]=value;announce(/^\s*-\s*\d+\s*$/.test(value)&&Number(value.replace('-',''))>0?'For an upper-only bound, enter 0-'+value.replace('-','').trim()+'.':'Range updated in this fixture.');},{id:key,help:'Examples: 100-5000, 100- or 0-5000. Empty means no limit.'});}
  else{const matching=section(root,'Matching');input(matching,'Excluded text',item.excludeStrings,value=>item.excludeStrings=value,{multiline:true,id:'excluded-text',help:'Comma-separated, case-insensitive phrases contained in comment text.'});input(matching,'Excluded users',item.excludeUsers,value=>item.excludeUsers=value,{multiline:true,id:'excluded-users',help:'Comma-separated exact usernames; case does not matter.'});button(matching,'Choose users',()=>context.announce('Existing multi-user picker route. This study performs no live lookup.'));input(section(root,'Filtered comments'),'Display',item.displayMode,value=>item.displayMode=value,{id:'display-mode',options:[['0','Remove comment'],['10','Collapse comment']]});const limits=section(root,'Votes');input(limits,'Minimum votes',item.minVote,value=>item.minVote=value,{id:'minimum-votes',help:'Only positive values apply. Empty means no minimum.'});input(limits,'Maximum votes',item.maxVote,value=>item.maxVote=value,{id:'maximum-votes',help:'Only positive values apply. Empty means no maximum.'});note(root,'Subreddit assignments are managed separately through Apply to.');}
  button(root,'Save filter',save,'filter-save');
 }
 const status=el('div','field-help');status.id='filter-feedback';status.setAttribute('role','status');root.append(status);
}
window.RelaxeFilterStudy={render(root,account,view,navigate,announce,goBack){const kind=view.startsWith('post-')?'post':'comment';context={root,account,kind,view,data:store(account,kind),navigate,announce,goBack};draw()},requestExit(action){if(!context?.view.endsWith('-editor')||!dirty()){action();return}confirm('Discard filter changes?','Your unsaved filter changes will be lost.','Discard changes',()=>{session=null;action()},'Keep editing')},discardSession(){session=null},isModalOpen(){return !!document.getElementById('filter-modal')?.open}};
})();
